scenes.code:
fn main() {
    let mut number = 3;
    while number != 0 {
        println!("{number}!");
        number -= 1;
    }
    println!("LIFTOFF!");
}

fn main() {
    let a = [10, 20, 30];
    for x in a {
        println!("{x}");
    }
}

fn main() {
    let a = [10, 20, 30];
    let mut i = 0;
    while i <= 3 {
        println!("{}", a[i]);
        i += 1;
    }
}
